/**
 * Portfolio data. Every page reads from here (homepage, /work, /work/:slug).
 * To add a project: copy one object, change the fields, drop images into public/images/projects/.
 *   thumbnail  → /images/projects/<slug>.jpg           (card image, 4:5 or 16:10 crop works well)
 *   gallery    → /images/projects/<slug>-01.jpg …      (generated by gallery() below)
 *   video      → optional short looping preview shown on desktop hover (MP4, no audio needed)
 */

const gallery = (slug, captions) =>
  captions.map((alt, index) => ({
    src: `/images/projects/${slug}-${String(index + 1).padStart(2, '0')}.jpg`,
    alt,
    layout: index % 3 === 0 ? 'wide' : 'tall',
  }))

